effect.shader:
// Depth-based parallax displacement
// Inputs: inputImg (depth map on the current layer), comp (underlying composition)

const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);

float getDepth(vec2 uv){
  vec4 d = texture2DCv(inputImg.texture, uv);
  float v;
  if(depthChannel==0){ v = dot(d.rgb, LUMA); }
  else if(depthChannel==1){ v = d.r; }
  else if(depthChannel==2){ v = d.g; }
  else if(depthChannel==3){ v = d.b; }
  else { v = dot(d.rgb, LUMA); }
  return invertDepth ? (1.0 - v) : v;
}

// Build a simple 3D-like view vector from position and Euler rotation
// rotX=pitch, rotY=yaw, rotZ=roll (degrees)
vec3 eulerToForward(float rx, float ry){
  float cx = cos(rx), sx = sin(rx);
  float cy = cos(ry), sy = sin(ry);
  // Start with forward along -Z, rotate by pitch (X) then yaw (Y)
  vec3 f = vec3(0.0, 0.0, -1.0);
  // pitch (X)
  f = vec3(f.x, f.y*cx - f.z*sx, f.y*sx + f.z*cx);
  // yaw (Y)
  f = vec3(f.x*cy + f.z*sy, f.y, -f.x*sy + f.z*cy);
  return normalize(f);
}

void main(){
  vec2 uv = acScreenNorm;
  vec4 depthSample = texture2DCv(inputImg.texture, uv);

  // Aspect-correct screen space for consistent displacement angles
  vec2 aspect = vec2(acScreenSize.x/acScreenSize.y, 1.0);

  // Convert degrees to radians
  float RX = rotX * 0.01745329252;
  float RY = rotY * 0.01745329252;
  float RZ = rotZ * 0.01745329252;

  // Forward/view direction from rotations
  vec3 fwd = eulerToForward(RX, RY);
  // Roll rotates the screen-plane direction around Z
  float cr = cos(RZ), sr = sin(RZ);
  vec2 rot2 = mat2(cr, -sr, sr, cr) * normalize(vec2(fwd.x, fwd.y) + 1e-6);

  // Compose 2D displacement direction from position controls and rotation-derived vector
  vec2 dir = vec2(posX, posY) + rot2 * posZ;
  // Aspect correction so a unit dir.x equals unit dir.y visually
  dir.x *= aspect.x;

  // Depth and displacement
  float depth = clamp(getDepth(uv), 0.0, 1.0);
  float strength = amp;
  vec2 displacedUV = uv + dir * (1.0 - depth) * strength;

  // Edge handling
  vec2 sampleUV = displacedUV;
  if(edges==0){
    // Repeat (clamped sampling handles repeat internally by mirroring logic below)
    sampleUV = displacedUV;
  } else if(edges==1){
    // Mirror
    sampleUV = vec2(1.0,1.0) - abs(mod(displacedUV, vec2(2.0)) - vec2(1.0));
  } else if(edges==2){
    if(displacedUV.x < 0.0 || displacedUV.x > 1.0 || displacedUV.y < 0.0 || displacedUV.y > 1.0){
      gl_FragColor = vec4(0.0);
      return;
    }
  } else if(edges==3){
    // Tile
    sampleUV = fract(displacedUV);
  }

  vec4 col = texture2DCv(comp.texture, sampleUV);
  // Multiply by depth layer alpha so masked areas remain transparent
  gl_FragColor = vec4(col.rgb, col.a * depthSample.a);
}
